pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address sender, uint256 amount) public {
        uint256 amt = bound(amount, 0, 1e18);

        vm.deal(sender, amt);

        vm.prank(sender);
        bool ok;
        try c.play{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || amt == 10);
    }
}
